bool[,] Reach(int[][] h, Queue<(int r, int c)> queue) {
    int rows = h.Length, cols = h[0].Length;
    var seen = new bool[rows, cols];
    foreach (var (r, c) in queue) seen[r, c] = true;    // the whole edge is the source
    int[] dr = { -1, 0, 1, 0 }, dc = { 0, 1, 0, -1 };
    while (queue.Count > 0) {
        var (r, c) = queue.Dequeue();
        for (int d = 0; d < 4; d++) {
            int y = r + dr[d], x = c + dc[d];
            if (y < 0 || x < 0 || y >= rows || x >= cols || seen[y, x]) continue;
            if (h[y][x] < h[r][c]) continue;              // against the flow: only up or level
            seen[y, x] = true;
            queue.Enqueue((y, x));
        }
    }
    return seen;
}
// pac: row 0 and column 0; atl: the last row and the last column
